document.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('choice-result').textContent=choices[Number(b.dataset.choice)];}));document.querySelectorAll('[data-device]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('.mini-screen').className='mini-screen '+b.dataset.device;document.querySelectorAll('[data-device]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}));document.querySelectorAll('[data-format]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('.video-frame').className='video-frame '+b.dataset.format;document.querySelectorAll('[data-format]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}));const motion=document.querySelector('.motion-toggle');motion.addEventListener('click',()=>{const v=document.body.classList.toggle('paused');motion.textContent=v?'Resume animations':'Pause animations';motion.setAttribute('aria-pressed',String(v))});const topButton=document.querySelector('.back-top');window.addEventListener('scroll',()=>{topButton.hidden=scrollY<350},{passive:true});topButton.addEventListener('click',()=>{window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('.logo').focus({preventScroll:true})});if(document.getElementById('budget-calc')){const calc=()=>{const b=Number(document.getElementById('budget-calc').value)||0,c=Number(document.getElementById('cpc').value)||0,rate=Number(document.getElementById('rate').value)||0;document.getElementById('clicks').textContent=c>0?Math.round(b/c).toLocaleString():'—';document.getElementById('leads').textContent=c>0?Math.round(b/c*rate/100).toLocaleString():'—'};document.querySelectorAll('.calc-input').forEach(el=>el.addEventListener('input',calc));calc()}if(document.getElementById('seo-title')){const update=()=>{document.getElementById('preview-title').textContent=document.getElementById('seo-title').value;document.getElementById('preview-desc').textContent=document.getElementById('seo-desc').value};document.getElementById('seo-title').addEventListener('input',update);document.getElementById('seo-desc').addEventListener('input',update)}document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>{const steps=['Choose a service','Pick a suitable time','Review and confirm'];const i=Number(b.dataset.step);document.getElementById('app-screen').textContent=steps[i];document.querySelectorAll('[data-step]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}));